package dev.martianzoo.tfm.carddata

internal object GeneratedCardDataResources {
  private val resources: Map<String, String> =
      buildMap {
        putAll(baseCardDataSources.resources)
        putAll(coloniesCardDataSources.resources)
        putAll(corperaCardDataSources.resources)
        putAll(preludeCardDataSources.resources)
        putAll(prelude2CardDataSources.resources)
        putAll(promosCardDataSources.resources)
        putAll(turmoilCardDataSources.resources)
        putAll(venusCardDataSources.resources)
      }

  internal val filenames: Set<String>
    get() = resources.keys

  internal fun read(filename: String): String =
      resources[filename] ?: error("Unknown catalog resource: $filename")
}
